body:
{
  "pains": [
    {
      "id": "pain:bill-grows-with-the-database",
      "statement": "Every contact we add makes the bill bigger, whether or not that contact ever buys anything.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "The invoice moves up after a webinar list import or a good month of form fills, with no change in what the team can actually do.",
        "operational": "Someone has to sit in the marketing contacts setting and decide which records to mark non-marketing or delete before the count crosses the next tier, and budgeting for the year becomes a guess about database growth.",
        "personal": null,
        "personal_note": "No source shows what this costs the person. The quotes stop at the budget and the invoice: the closest is a small-business owner describing GBP 1,000 leaving the bank account with no warning, which is still the company's money, not the person's standing. Looked in review sites and public complaint pages; asked as q:pains-personal-rung."
      },
      "workflow": "The annual budget line for marketing software, and then the monthly reconciliation between the subscription page and the marketing contacts count, at the step where a list import from a webinar or a form fill pushes the count past the tier ceiling and the next invoice moves.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A campaign or list import pushes the contact count past the allowance and the overage is billed before anyone notices.", "cites": ["src:45"] },
        { "event": "The annual renewal is repriced on new packaging, with a migration-related increase applied at renewal across rolling renewals in 2024-2025.", "cites": ["src:60"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "It's difficult for marketing to budget for the price", "cites": ["src:22"] },
            { "situation": "venting", "verbatim": "HubSpot in general nickle and dimes you on a lot of their services.", "cites": ["src:23"] },
            { "situation": "venting", "verbatim": "Pricing can become a challenge as you grow", "cites": ["src:21"] },
            { "situation": "when_it_bites", "verbatim": "Accidentally went over my allowance of contacts. I didn't use the contacts in any campaign and with no warning they took £1000 out of my bank account.", "cites": ["src:45"] }
          ],
          "costs_them": "A software line they cannot forecast, plus overage charges for records that ran in no campaign.",
          "fears": "That growth in the database keeps repricing the contract upward faster than the marketing it pays for returns anything.",
          "dream_outcome": "A price they can put in next year's budget that does not move because the contact count moved."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "Once you begin the addition of more contacts into the list, then the bill quickly skyrockets", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "cost jumps drastically as your contact database grows", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "Marketing contacts pricing structure can be confusing and some things are additional costs", "cites": ["src:26"] },
            { "situation": "venting", "verbatim": "HubSpot Marketing Hub costs can increase quickly as you scale contacts or unlock advanced features", "cites": ["src:16"] }
          ],
          "costs_them": "Time spent pruning and re-classifying contacts to hold a tier, and an argument to win every time the list grows.",
          "fears": "That the tool they brought in becomes the reason finance questions the marketing budget.",
          "dream_outcome": "Growing the list is good news, not a bill."
        }
      },
      "segments": ["seg:startup", "seg:midmarket", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company kills this; it is a packaging and pricing-model pain, not a product gap. What would kill it is a price that keys off usage the buyer connects to value (sends, seats, revenue) rather than stored records, or a free tier for non-marketing contacts that is on by default.",
      "cites": ["src:1", "src:2", "src:22", "src:45"]
    },
    {
      "id": "pain:the-thing-i-need-is-one-tier-up",
      "statement": "Every time I go to do the thing I bought this for, it turns out to be in the next plan up.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "An upgrade prompt where the A/B test, the custom report or the workflow branch should be.",
        "operational": "The team either builds a worse version of it by hand, buys an add-on, or opens a renegotiation with the vendor mid-year to unlock one feature.",
        "personal": null,
        "personal_note": "No source shows the personal cost. Reviewers describe the paywall and the price, not what it did to them at work. Asked as q:pains-personal-rung."
      },
      "workflow": "Building the campaign in the email and workflow editors, at the step where you try to split the send for an A/B test or add a branch, and again in the custom report builder when the report you sketched for the monthly review needs a field the plan does not expose.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The team runs its first A/B test or builds its first custom report and finds both are Professional-only.", "cites": ["src:3", "src:18"] },
        { "event": "Headcount grows and the included core seats run out, so more users have to be bought before anyone can log in.", "cites": ["src:9"] }
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "AI workflows, custom reports, and A/B testing are locked behind Professional tiers", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "Most of the important features other than the basic CRM and messaging are in the pro package which can be expensive.", "cites": ["src:24"] },
            { "situation": "venting", "verbatim": "The price is astronomical for what it is.", "cites": ["src:29"] },
            { "situation": "when_it_bites", "verbatim": "The price is just getting out of control. All the best features continue to get pay walled behind subscriptions", "cites": ["src:12"] }
          ],
          "costs_them": "A plan that covers the demo but not the job, and a second budget conversation months after the first one was won.",
          "fears": "That the roadmap they promised internally is gated behind money they were not given.",
          "dream_outcome": "The features they were shown in the demo work on the plan they were sold."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "many of the more powerful tools are locked behind paywalls", "cites": ["src:4"] },
            { "situation": "venting", "verbatim": "The more I use this software the less I like it. It seems good upfront but unless you pay thousands each month everything is severely limited.", "cites": ["src:48"] },
            { "situation": "venting", "verbatim": "That many of the core features are locked behind higher plans that are not cost effective", "cites": ["src:52"] },
            { "situation": "venting", "verbatim": "The main downside is that some useful automation and advanced sales features are limited to higher-tier", "cites": ["src:54"] }
          ],
          "costs_them": "Manual versions of automated work, done in the tool they were told would automate it.",
          "fears": "That the tool stays half-useful for as long as they work here.",
          "dream_outcome": "The features that make the tool worth using are in the plan the company actually bought."
        }
      },
      "segments": ["seg:startup", "seg:midmarket", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No feature listed in brain/company kills this, because the pain is which tier a feature sits in rather than whether it exists. What would kill it: the automation and reporting capability that buyers treat as basic being present at the entry tier, or a usage-based unlock instead of a plan-based one.",
      "cites": ["src:3", "src:12", "src:48", "src:52"]
    },
    {
      "id": "pain:cant-get-out-of-the-contract",
      "statement": "I stopped using it months ago and I am still paying for it, because I missed a cancellation window I did not know existed.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "A renewal invoice for another twelve months, after a renewal notice that arrived among marketing emails.",
        "operational": "Chasing a rep and then a billing team to undo it, then keeping the seats and the subscription alive on paper to the end of the term while the work moves somewhere else.",
        "personal": "The owner who signed it carries it personally: one says it is now cheaper to close the company and start a new one than to keep paying.",
        "personal_note": "Filled from a single owner's quote (src:36); treat as one voice, not a pattern, until a second owner says it."
      },
      "workflow": "The renewal date in the subscription and billing settings, at the step 30 days or more before it where auto-renewal has to be switched off, against an inbox where the renewal notice sits next to product marketing.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The cancellation window closes ahead of the renewal date and the term rolls for another year.", "cites": ["src:30", "src:42"] },
        { "event": "A cash crunch or downturn makes the subscription unaffordable mid-term, when mid-term cancellation is not available.", "cites": ["src:36"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "I missed cancelling components of my contract by a week, and it auto-renewed, and the customer service rep refused to adjust my contract.", "cites": ["src:30"] },
            { "situation": "venting", "verbatim": "They sneak an annual contract in there and you cannot get out of it. They wouldn't refund my money.", "cites": ["src:46"] },
            { "situation": "when_refusing", "verbatim": "locked into a 12-month contract and can't cancel early", "cites": ["src:42"] },
            { "situation": "venting", "verbatim": "It is now cheaper for us to close the company and start a new one, than to keep paying Hubspot!!", "cites": ["src:36"] },
            { "situation": "when_it_bites", "verbatim": "paid nearly £2k in subscription that has ultimately never been used", "cites": ["src:44"] },
            { "situation": "venting", "verbatim": "Changed terms of contract after signing, reduced number of seats without informing in advance.", "cites": ["src:38"] }
          ],
          "costs_them": "Months of subscription for software the business has stopped using, with no refund route.",
          "fears": "That signing anything here means a year of payments regardless of whether it works.",
          "dream_outcome": "Being able to leave at the end of a month, or at least being told clearly when the door closes."
        }
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No product feature kills this; it is a contract and billing-policy pain. What would kill it is a plain renewal notice sent outside the marketing stream, a visible cancellation date in the billing screen, and a monthly option that is genuinely monthly.",
      "cites": ["src:30", "src:42", "src:46"]
    },
    {
      "id": "pain:sold-one-thing-got-another",
      "statement": "The rep said it would do the thing we needed, we signed and paid the onboarding fee, and then found out it does not.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Implementation starts and the specific job the deal was bought for turns out to need another platform, another add-on or another fee.",
        "operational": "Buying the third-party tool anyway, or paying for extra services, while still paying for the subscription that was supposed to cover it.",
        "personal": null,
        "personal_note": "No source shows what it cost the person who championed the purchase. Reviewers write as the company. Looked across review sites and complaint pages; asked as q:pains-personal-rung."
      },
      "workflow": "The gap between the demo call, where the use case is confirmed live, and the first weeks of implementation in the portal, at the step where the promised capability is configured and turns out to need something that was not in the quote.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Implementation begins and the demo-to-build gap shows up, after the annual contract and onboarding fee are already paid.", "cites": ["src:31", "src:49"] },
        { "event": "The buyer tries to cancel on the strength of a verbal assurance that the subscription was cancellable at any time.", "cites": ["src:50"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "once we paid and signed an annual contract and paid the onboarding fee we were told we actually did need a third party platform.", "cites": ["src:31"] },
            { "situation": "when_it_bites", "verbatim": "I was assured by the HubSpot sales representative that my 'monthly' subscription could be canceled at any time, a key factor in my sign-up. However, when the service underperformed and I tried to cancel before renewal, the process became impossible.", "cites": ["src:50"] },
            { "situation": "when_refusing", "verbatim": "We were completely missold and then dropped the second the contract was signed/over the line.", "cites": ["src:35"] }
          ],
          "costs_them": "A year of committed spend plus an onboarding fee for a setup that still needs another product bought on top.",
          "fears": "That nothing said on a sales call can be relied on once the signature is in.",
          "dream_outcome": "What was demonstrated on the call is what is running in the portal 30 days later."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "We were assured of the sales representative, Alana who claimed it could handle specific tasks crucial to my business. Unfortunately, after implementation, I discovered that the CRM could not perform these tasks as promised.", "cites": ["src:49"] },
            { "situation": "venting", "verbatim": "the service we've had has been appalling most notably in terms of mis-selling.", "cites": ["src:34"] },
            { "situation": "venting", "verbatim": "They will lie to you are make false promises of what this CRM can do just to lock you into a contract paying thousands for an unusable product.", "cites": ["src:41"] }
          ],
          "costs_them": "Weeks of implementation work that cannot deliver the thing they promised it would deliver.",
          "fears": "That they are the one who brought in a platform that cannot do the job it was chosen for.",
          "dream_outcome": "A written, checkable answer on whether their specific use case works, before the contract, not after."
        }
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses this; it sits in the sales and onboarding motion. What would kill it is a pre-sale technical validation of the buyer's named use case, written into the order form, and a refund window tied to it.",
      "cites": ["src:31", "src:49", "src:34"]
    },
    {
      "id": "pain:nobody-answers-after-you-pay",
      "statement": "Before I paid, someone called me every day. After I paid, the answer is a help article.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "A broken setup or a billing problem, and no reachable human: a knowledge-base link, a slow ticket, or a channel that only exists for sales.",
        "operational": "The team self-serves through tutorials and forum posts, or pays for a partner or an upgrade to get support at all.",
        "personal": "The person who has to fix it reads generic articles while their own customers wait, and one beginner describes being unable to find any help resource that worked for them.",
        "personal_note": "Filled from src:11 and src:25; both describe the person's own experience of being left to it, not a wider cost like a review or a lost job."
      },
      "workflow": "The moment after go-live when something breaks in the portal - a tax setting on invoices, an API token change, a sync that stops - and the only routes are the in-app help widget, a ticket queue and the knowledge base.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Something breaks after go-live and the only available channel returns generic articles.", "cites": ["src:11", "src:47"] },
        { "event": "A free or low-tier account hits a problem and support turns out to require an upgrade.", "cites": ["src:51"] }
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "You cannot speak to anyone over the phone unless they are selling you the product! You make payment and they disconnect you!", "cites": ["src:47"] },
            { "situation": "venting", "verbatim": "Hubspot customer services is simply the worst I've encountered in recent history.", "cites": ["src:32"] },
            { "situation": "venting", "verbatim": "Customer support and account managers were useless", "cites": ["src:8"] },
            { "situation": "venting", "verbatim": "They give you a free account, but then lock your account and require that you 'upgrade' to get any support whatsoever.", "cites": ["src:51"] }
          ],
          "costs_them": "Days of downtime on a paid platform and the internal position of having to explain why nobody is helping.",
          "fears": "That the next serious outage or billing error has no path to resolution at all.",
          "dream_outcome": "A named human who answers when the thing they bought stops working."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "the customer service usually only directs you to some generic articles", "cites": ["src:11"] },
            { "situation": "when_it_bites", "verbatim": "I had no idea how to use it. I found it difficult to navigate as a beginner and I couldn't find any help resources that worked for me.", "cites": ["src:25"] },
            { "situation": "venting", "verbatim": "absolutely ZERO support whatsoever. You are in the woods. Fact.", "cites": ["src:37"] },
            { "situation": "venting", "verbatim": "The support isn't always the most helpful. There have been times when we haven't been notified of significant changes to thinks like API tokens and integrations.", "cites": ["src:28"] }
          ],
          "costs_them": "Hours lost to searching for an answer that a support reply would have given in five minutes.",
          "fears": "Being blamed for a problem in a system they were never properly helped to learn.",
          "dream_outcome": "Getting a real answer the same day, without having to be a paying-tier customer to ask."
        }
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers support responsiveness. feat:agent (AI agents across the funnel) is the nearest thing and cuts both ways: the quotes here are about generic canned answers, which is exactly what an unsupervised agent produces more of. What would kill it is human support at the tier the buyer is actually on, with a response-time commitment.",
      "cites": ["src:47", "src:32", "src:11"]
    },
    {
      "id": "pain:cant-build-the-report-that-proves-it",
      "statement": "I can pull the campaign metrics, but I cannot build the one view that shows what the spend actually returned.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "The report builder will not give the cut being asked for: the segmentation, the attribution, the slice across objects.",
        "operational": "The numbers get exported and rebuilt by hand in a spreadsheet or an external BI tool, or an add-on gets bought to answer one question.",
        "personal": null,
        "personal_note": "No source shows the personal cost of not being able to prove the work. Reviewers describe the tool's limits, not the meeting where the number was missing. Asked as q:pains-report-moment."
      },
      "workflow": "The monthly or quarterly review deck, at the step where campaign data has to be turned into a revenue or segment view: the custom report builder first, then an export into a spreadsheet or Looker Studio when the builder will not cut it, and a Google Analytics tab open alongside for what the native reports do not show.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "The question moves from campaign metrics to segmentation and attribution, and the native reporting stops short.", "cites": ["src:27", "src:20"] },
        { "event": "The advanced reporting needed turns out to be a higher-tier or add-on purchase.", "cites": ["src:3", "src:18"] }
      ],
      "who_feels": ["champion", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "In terms of reporting options, the HubSpot Marketing Hub falls short of being the most complete. For instance, it is unable to give in-depth client segmentation.", "cites": ["src:27"] },
            { "situation": "venting", "verbatim": "Reporting customization could also be more flexible", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "limitations when it came to data and analysis", "cites": ["src:20"] },
            { "situation": "venting", "verbatim": "Some settings and reports take a little digging to find", "cites": ["src:7"] }
          ],
          "costs_them": "Hours rebuilding in a spreadsheet what the platform was bought to produce, every reporting cycle.",
          "fears": "That they cannot show the return on the budget they asked for, and the budget goes.",
          "dream_outcome": "One view, built once, that answers what the spend returned without an export."
        },
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "Tools like A/B testing or advanced reporting are only available on higher tier plans", "cites": ["src:18"] },
            { "situation": "venting", "verbatim": "AI workflows, custom reports, and A/B testing are locked behind Professional tiers", "cites": ["src:3"] }
          ],
          "costs_them": "Paying twice for visibility: once for the platform, again for the tier or add-on that reports on it.",
          "fears": "Approving renewal on a platform whose contribution they cannot measure.",
          "dream_outcome": "Reporting good enough to decide next year's budget on, included in the plan they already pay for."
        }
      },
      "segments": ["seg:midmarket", "seg:agency"],
      "feature_ref": "feat:data",
      "feature_note": "feat:data (Data Hub, unifies customer data across tools) is the closest fit, but the quotes are about report-building depth and tier gating inside the product, not only about data sitting in other tools. Treat the link as partial until a customer confirms the report they could not build.",
      "cites": ["src:27", "src:5", "src:20"]
    },
    {
      "id": "pain:lost-in-the-product",
      "statement": "There is so much in here that finding the one screen I need takes longer than the job itself.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Menus inside menus, settings that move, and a search that does not find the old record.",
        "operational": "People cross-reference their email to find things that should be in the tool, and new starters go through tutorial videos before they can do routine work.",
        "personal": "A new starter describes spending more time watching tutorial videos than actually using the tool.",
        "personal_note": "Filled from one end user's quote (src:15); a single voice, not yet a pattern."
      },
      "workflow": "The daily loop in the CRM and ticket views: finding an older ticket or record without knowing its exact title, which sends the user back to Outlook to cross-reference the email thread, and the first two weeks of a new starter's onboarding in the same screens.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A new starter is onboarded and has to find their way around without a working help path.", "cites": ["src:25", "src:14"] },
        { "event": "The interface changes and previously known screens have to be relearned.", "cites": ["src:39"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "HubSpot has a lot of features, but it feels too complicated. There are so many menus and settings that it's hard to use, especially if you just want something straightforward.", "cites": ["src:43"] },
            { "situation": "when_it_bites", "verbatim": "It can be difficult to find older tickets unless I know the exact title, which often means cross-referencing emails.", "cites": ["src:58"] },
            { "situation": "venting", "verbatim": "It's a bit complicated to navigate. There's a lot of different pages with sub pages", "cites": ["src:53"] },
            { "situation": "when_it_bites", "verbatim": "I spent more time watching tutorial videos than actually using it", "cites": ["src:15"] },
            { "situation": "venting", "verbatim": "The UX design and navigation is not very clear. Hard to navigate when you are new the the software", "cites": ["src:14"] },
            { "situation": "venting", "verbatim": "To much going on and can seem like you get lost with the options", "cites": ["src:19"] }
          ],
          "costs_them": "Minutes per lookup, several times a day, plus weeks of ramp before the tool pays back.",
          "fears": "That they will keep looking slow at their job because the tool hides the work.",
          "dream_outcome": "Find any record or ticket in one search, and know where the setting lives without a tutorial."
        }
      },
      "segments": ["seg:startup", "seg:midmarket", "seg:agency"],
      "feature_ref": "feat:smartcrm",
      "feature_note": "feat:smartcrm (one customer record the hubs share) is the feature aimed at this: one record found once rather than cross-referenced from email. The quotes say the promise is not yet landing in search and navigation, which is a finding for positioning, not a reason to drop the link.",
      "cites": ["src:43", "src:58", "src:53"]
    },
    {
      "id": "pain:hand-carried-data-between-systems",
      "statement": "The CRM and the systems that actually run the business never quite meet, so somebody moves the data by hand.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "A manual upload, a CSV that will not format, an integration that hits a limit.",
        "operational": "A standing manual step in someone's week: export from one system, clean the file, upload into the other, and repeat it next week because it is just how it is done here.",
        "personal": null,
        "personal_note": "No source shows the personal cost. This is a latent pain: the people doing it describe the mechanics flatly and do not complain about what it does to them, which is the tell. Asked as q:pains-manual-steps."
      },
      "workflow": "The weekly or monthly sync between the CRM and the systems of record - NetSuite, an LMS, the finance stack - at the step where no supported integration covers the field being moved, so the file is exported, fixed in a spreadsheet and uploaded by hand.",
      "type": "latent",
      "revealed_by": "feat:data",
      "confidence": "medium",
      "triggers": [
        { "event": "A system outside the suite (ERP, LMS) has to reconcile with CRM records and no supported integration covers it.", "cites": ["src:17"] },
        { "event": "A large contact list has to be moved and the file formatting becomes the job.", "cites": ["src:6"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "integration limit with our LMS, requires manual upload from the NetSuite", "cites": ["src:17"] },
            { "situation": "when_it_bites", "verbatim": "I have had to deal with CSV formatting problems", "cites": ["src:6"] },
            { "situation": "when_comparing", "verbatim": "Limited integrations in comparison to Salesforce", "cites": ["src:56"] },
            { "situation": "venting", "verbatim": "Wish it was easier to integrate with other platforms.", "cites": ["src:13"] }
